24	export async function recordAttendance(cardId: string): Promise<{ success: boolean; message: string; user: { display_name: string | null; } | null; type: 'in' | 'out' | null; }> {
25	  const TIMEOUT_MS = 10000; // 10秒タイムアウト
26	  const traceId = randomUUID();
27	  
28	  const timeoutPromise = new Promise<never>((_, reject) => {
29	    setTimeout(() => reject(new Error('TIMEOUT')), TIMEOUT_MS);
30	  });
31	
32	  try {
33	    return await Promise.race([
34	      recordAttendanceInternal(cardId, traceId),
35	      timeoutPromise
36	    ]);
37	  } catch (error) {
